import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.ChunkRadiusUpdated{ChunkRadius: 12}
RADIUS = bytes.fromhex("18")

# generated by gophertunnel b8bd735:
# &packet.ChunkRadiusUpdated{ChunkRadius: -1}
NEGATIVE_RADIUS = bytes.fromhex("01")

# generated by gophertunnel b8bd735:
# &packet.ChunkRadiusUpdated{ChunkRadius: 200}
WIDE_RADIUS = bytes.fromhex("9003")

GOLDENS = [
    pytest.param(v2225.ChunkRadiusUpdatedPacket(chunk_radius=12), RADIUS, id="radius"),
    pytest.param(v2225.ChunkRadiusUpdatedPacket(chunk_radius=-1), NEGATIVE_RADIUS, id="negative-radius"),
    pytest.param(v2225.ChunkRadiusUpdatedPacket(chunk_radius=200), WIDE_RADIUS, id="wide-radius"),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_chunk_radius_updated_is_packet_70(version):
    assert version.PACKETS[70] is version.ChunkRadiusUpdatedPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_chunk_radius_updated_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_chunk_radius_updated_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
